            &identity_path,
            declaration_resolution::observation_schema(),
            &malformed,
        )
        .await?;
        let error = storage
            .read_declaration_load()
            .await
            .err()
            .expect("unknown label rejected");
        assert!(
            error
                .to_string()
                .contains("unknown variant `unknown_resolution_label`"),
