            'funders', (SELECT jsonb_agg(to_jsonb(row) ORDER BY id) FROM exposed.funders AS row),
            'aliases', (SELECT jsonb_agg(to_jsonb(row) ORDER BY funder_id, funder_alias) FROM exposed.funder_aliases AS row),
